def solve_a(n_limit):
    a = [0] * (n_limit + 1)
    a[1] = 0
    for n in range(2, n_limit + 1):
        res = 0
        for i in range(1, n):
            res = max(res, a[i] + a[n-i] + min(i, n-i))
        a[n] = res
    return a

a_vals = solve_a(100)
for i in range(1, 101):
    print(f"a_{i} = {a_vals[i]}", end="; ")

def solve_a_fast(n_limit):
    a = [0] * (n_limit + 1)
    a[1] = 0
    for n in range(2, n_limit + 1):
        res = 0
        for i in range(1, (n // 2) + 1):
            val = a[i] + a[n-i] + i
            if val > res:
                res = val
        a[n] = res
    return a[n_limit]

print(solve_a_fast(2025))
